def choose_move(observation):
    px, py = observation['self_position']
    target = None
    min_dist = float('inf')
    for res in observation.get('resources', []):
        rx, ry = res['pos']
        d = abs(px - rx) + abs(py - ry)
        if d < min_dist:
            min_dist = d
            target = (rx, ry)
    if target is None:
        return [0, 0]
    dx = dy = 0
    if target[0] > px:
        dx = 1
    elif target[0] < px:
        dx = -1
    elif target[1] > py:
        dy = 1
    elif target[1] < py:
        dy = -1
    return [dx, dy]
